type ComplexParser<'a, 'b, 'c, T> = Box
    dyn Fn(&'a str, &'b str) -> (&'c str, T) + 'a + 'b
    //     ^^^^^^  ^^^^^^       ^^^^^^        ^^^^^^^
    //     |       |            |             Trait object bounds:
    //     |       |            |             "can capture 'a and 'b refs"
    //     |       |            Return lifetime
    //     |       Second parameter
    //     First parameter
>;

type ParserResult<'a, T> = Option<(T, T)>;
type Parser<'a, T> = Box<dyn Fn(&T) -> ParserResult<'a, T> + 'a>; // Parser is holding a closure
//                                                            ^--- it's a lifetime of a capturing
//                                                            reference, w/o explicit, it will
//                                                            use 'static !!!
